def _acceptance_numeric_constraints(requirement: str) -> list[str]:
    """Extrahiert explizite Zahlen nur aus Anforderungen mit erkennbarer Grenz-/Wertsemantik."""
    text = " ".join(str(requirement or "").lower().split())
    constrained = re.search(
        r"\b(?:max(?:imal)?|höchstens|mindestens|limit|begrenz|zeichen|bytes?|kb|mb|gb|sekunden?|minuten?|stunden?|tage?|prozent)\b|(?:=|<=|>=|<|>)\s*\d",
        text,
    )
    if not constrained:
        return []
    return re.findall(r"(?<![\w.])\d+(?:[.,]\d+)?(?![\w.])", text)

